<script setup lang="ts">
import { RotateCcw, Check } from 'lucide-vue-next'
import { assetUrl, centerCrop, type Asset, type ImageSpec, type CropRect } from '@qinbian/shared'
const props=defineProps<{assetId:string;spec?:ImageSpec}>(),emit=defineEmits<{close:[];apply:[asset:Asset,spec:ImageSpec]}>(),ctx=useQinbian()
const source=ref<Asset>(),shape=ref<ImageSpec['shape']>(props.spec?.shape||'rect'),ratio=ref(props.spec?.ratio||0),radius=ref(props.spec?.radius??.08),zoom=ref(1),cx=ref(.5),cy=ref(.5),loading=ref(true),saving=ref(false),error=ref(''),stage=ref<HTMLElement>()
const outputRatio=computed(()=>shape.value==='circle'?1:ratio.value||((source.value?.width||1)/(source.value?.height||1)))
const rect=computed<CropRect>(()=>{const base=centerCrop(source.value?.width||1,source.value?.height||1,outputRatio.value),w=base.width/zoom.value,h=base.height/zoom.value;return{x:Math.max(0,Math.min(1-w,cx.value-w/2)),y:Math.max(0,Math.min(1-h,cy.value-h/2)),width:w,height:h}})
const previewStyle=computed(()=>({width:100/rect.value.width+'%',height:100/rect.value.height+'%',left:-rect.value.x/rect.value.width*100+'%',top:-rect.value.y/rect.value.height*100+'%'}))
const presets=[{label:'原图比例',value:0},{label:'正方形 · 1:1',value:1},{label:'横幅 · 4:3',value:4/3},{label:'竖幅 · 3:4',value:3/4},{label:'宽幅 · 16:9',value:16/9}]
const ratioOptions=computed(()=>[...(ratio.value&&!presets.some(p=>Math.abs(p.value-ratio.value)<.00001)?[{value:ratio.value,label:'组件比例 · '+ratio.value.toFixed(2)+':1'}]:[]),...presets])
let dragging:{x:number;y:number;cx:number;cy:number;rect:CropRect;width:number;height:number}|null=null
function reset(){if(shape.value==='circle')ratio.value=1;zoom.value=1;cx.value=cy.value=.5}
function start(e:PointerEvent){if(!stage.value||!source.value)return;const box=stage.value.getBoundingClientRect();cx.value=rect.value.x+rect.value.width/2;cy.value=rect.value.y+rect.value.height/2;dragging={x:e.clientX,y:e.clientY,cx:cx.value,cy:cy.value,rect:{...rect.value},width:box.width,height:box.height};stage.value.setPointerCapture(e.pointerId)}
function move(e:PointerEvent){if(!dragging)return;const d=dragging;cx.value=Math.max(d.rect.width/2,Math.min(1-d.rect.width/2,d.cx-(e.clientX-d.x)/d.width*d.rect.width));cy.value=Math.max(d.rect.height/2,Math.min(1-d.rect.height/2,d.cy-(e.clientY-d.y)/d.height*d.rect.height))}
onMounted(async()=>{try{const selected=await apiFetch<Asset>('/api/assets/'+props.assetId);source.value=selected.sourceAssetId?await apiFetch<Asset>('/api/assets/'+selected.sourceAssetId):selected;const old=selected.crop;if(old){shape.value=old.spec.shape;ratio.value=old.spec.ratio||selected.width/selected.height;radius.value=old.spec.radius??.08;const b=centerCrop(source.value.width,source.value.height,outputRatio.value);zoom.value=Math.max(1,Math.min(8,b.width/old.rect.width));cx.value=old.rect.x+old.rect.width/2;cy.value=old.rect.y+old.rect.height/2}}catch(e){error.value='原图暂时无法打开，请关闭后重试';ctx.error(e)}finally{loading.value=false}})
async function apply(){if(!source.value||saving.value)return;saving.value=true;error.value='';try{const spec:ImageSpec={shape:shape.value,...(ratio.value||shape.value==='circle'?{ratio:outputRatio.value}:{}),...(shape.value==='rounded'?{radius:radius.value}:{})};const a=await apiFetch<Asset>('/api/assets/'+source.value.id+'/crop',{method:'POST',body:{spec,rect:rect.value}});emit('apply',a,spec)}catch(e){error.value='裁切未完成，原图和正文没有改变';ctx.error(e)}finally{saving.value=false}}
</script>
<template><UiModal title="调整图片裁切" subtitle="拖动画面调整位置，放大后可精细取景。原图始终保留。" @close="!saving&&emit('close')"><p v-if="loading" class="muted">正在打开原图…</p><div v-else-if="source" class="crop-editor"><div class="crop-stage-wrap"><div ref="stage" class="crop-stage" role="img" aria-label="裁切预览，可拖动图片" :style="{width:Math.min(340,340*outputRatio)+'px',aspectRatio:String(outputRatio),borderRadius:shape==='circle'?'50%':shape==='rounded'?radius*100+'%':'0'}" @pointerdown.prevent="start" @pointermove="move" @pointerup="dragging=null" @pointercancel="dragging=null"><img :src="assetUrl(source.id)" :alt="source.name" :style="previewStyle" draggable="false"></div></div><div class="two-fields"><label>图片形状<UiSelect v-model="shape" :options="[{value:'rect',label:'矩形'},{value:'circle',label:'圆形'},{value:'rounded',label:'圆角'}]" aria-label="图片形状" @change="reset"/></label><label>裁切比例<UiSelect v-model="ratio" :options="ratioOptions" aria-label="裁切比例" :disabled="shape==='circle'" @change="reset"/></label></div><label>放大取景 <output>{{zoom.toFixed(1)}} 倍</output><input v-model.number="zoom" aria-label="放大取景" type="range" min="1" max="8" step="0.05"></label><div class="two-fields"><label>水平位置<input v-model.number="cx" aria-label="水平位置" type="range" :min="rect.width/2" :max="1-rect.width/2" step="0.005"></label><label>垂直位置<input v-model.number="cy" aria-label="垂直位置" type="range" :min="rect.height/2" :max="1-rect.height/2" step="0.005"></label></div><label v-if="shape==='rounded'">圆角幅度<input v-model.number="radius" aria-label="圆角幅度" type="range" min="0.02" max="0.5" step="0.01"></label><p class="small muted">{{source.width}} × {{source.height}} · {{source.mime==='image/gif'?'动图逐帧裁切，保留动画':'保存为独立的裁切副本，可重新调整'}}</p><div class="modal-actions"><button class="btn" :disabled="saving" @click="reset"><RotateCcw :size="14"/>居中重置</button><button class="btn primary" :disabled="saving" @click="apply"><Check :size="14"/>{{saving?'正在裁切…':'应用裁切'}}</button></div></div><p v-if="error" class="crop-error" role="alert">{{error}}</p></UiModal></template>
<style scoped>
.crop-editor{display:grid;gap:18px;min-width:0}.crop-stage-wrap{display:flex;justify-content:center;min-width:0;width:100%;box-sizing:border-box;padding:16px;background:repeating-conic-gradient(#e8e5de 0% 25%,#f8f6f0 0% 50%) 0 0/20px 20px;border:1px solid var(--line,#ded9cd)}.crop-stage{position:relative;max-width:100%;overflow:hidden;touch-action:none;cursor:grab;box-shadow:0 0 0 1px #a5a89b;user-select:none}.crop-stage:active{cursor:grabbing}.crop-stage img{position:absolute;max-width:none!important;display:block;pointer-events:none}.crop-editor .two-fields{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.crop-editor label{display:grid;gap:8px;font-size:13px;min-width:0}.crop-editor select,.crop-editor input{width:100%;min-width:0;box-sizing:border-box}.crop-editor input[type=range]{padding:0;accent-color:#183a49}.crop-editor output{font-size:11px;color:#6e7a72}.crop-error{color:#9e4b3b;font-size:13px}
</style>
